/* box_menu */
.bg_menu{
    width: 100%;
   background: #DE002B;
}
.box_menu{
    max-width: 1170px;
    margin: 0 auto;
    width: 100%;
}
.box_menu ul{
    margin: 0;
    padding: 0;
    list-style: none;
    overflow: hidden;
}
.box_menu li a{
    display: block;
    padding: 10px 35px;
    text-decoration: none;
    font-size: 12px;
    color: #fff;
    transition-property: all;
    transition-duration: 0.4s;
    font-weight: 900;
    text-transform: uppercase;
    letter-spacing: 1px;
}
.box_menu li a:hover,
.box_menu .menu-btn:hover{
    background-color: #303E47;
}
.box_menu .social{
    display: none;
}
/*.box_menu .social img{
    width: 100%;
}*/
/* menu */
.box_menu .menu{
    clear: both;
    max-height: 0;
    transition: max-height .2s ease-out;
}
/* menu icon */
.box_menu .menu-icon{
    cursor: pointer;
    display: inline-block;
    float: right;
    padding: 28px 20px;
    position: relative;
    user-select: none;
    top: 5px;
}
.box_menu .menu-icon .navicon{
    background: #ffffff;
    display: block;
    height: 2px;
    position: relative;
    transition: background .2s ease-out;
    width: 18px;
}
.box_menu .menu-icon .navicon:before,
.box_menu .menu-icon .navicon:after{
    background: #ffffff;
    content: '';
    display: block;
    height: 100%;
    position: absolute;
    transition: all .2s ease-out;
    width: 100%;
}
.box_menu .menu-icon .navicon:before{
    top: 5px;
}
.box_menu .menu-icon .navicon:after{
    top: -5px;
}
/* menu btn */
.box_menu .menu-btn{
    display: none;
}
.box_menu .menu-btn:checked ~ .menu{
    max-height: 240px;
}
.box_menu .menu-btn:checked ~ .menu-icon .navicon{
    background: transparent;
}
.box_menu .menu-btn:checked ~ .menu-icon .navicon:before{
    transform: rotate(-45deg);
}
.box_menu .menu-btn:checked ~ .menu-icon .navicon:after{
    transform: rotate(45deg);
}
.box_menu .menu-btn:checked ~ .menu-icon:not(.steps) .navicon:before,
.box_menu .menu-btn:checked ~ .menu-icon:not(.steps) .navicon:after{
    top: 0;
}
/* 48em = 768px */
@media (min-width: 768px){
    .box_menu li{
        float: left;
    }
    .box_menu li a{
        padding: 14px 20px 14px 20px;
    }
    .box_menu .menu{
        clear: none;
        float: left;
        max-height: none;
    }
    .box_menu .menu-icon{
        display: none;
    }
    .box_menu .social{
        width: 80px;
        display: block;
        float: right;
        padding: 10px;
    }
    .box_menu .social img{
        width: 20px;
    }
}
